package co.edu.cinematch.core.service;
import co.edu.cinematch.core.exception.*;import co.edu.cinematch.core.model.*;import co.edu.cinematch.core.repository.*;import java.time.*;import java.util.*;
public class ReservaService {private final Repository<Reserva> repo;private final AuthService auth;private final FuncionService funciones;private final CineService cines;public ReservaService(Repository<Reserva>r,AuthService a,FuncionService f,CineService c){repo=r;auth=a;funciones=f;cines=c;}public Reserva crear(String clienteId,String funcionId){Usuario u=auth.buscar(clienteId);if(u.getRol()!=Rol.CLIENTE)throw new ValidationException("La reserva debe pertenecer a un cliente.");funciones.buscar(funcionId);return repo.save(new Reserva(clienteId,funcionId,LocalDate.now()));}public Reserva agregarAsiento(String reservaId,String asientoId){Reserva r=buscar(reservaId);if(r.getEstado()==EstadoReserva.CANCELADA)throw new ValidationException("No se pueden agregar asientos a una reserva cancelada.");Funcion f=funciones.buscar(r.getFuncionId());Asiento a=cines.buscarAsiento(asientoId);if(!f.getSalaId().equals(a.getSalaId()))throw new ValidationException("El asiento no pertenece a la sala de la función.");if(a.isOcupado())throw new ValidationException("El asiento no está disponible.");a.setOcupado(true);r.getAsientoIds().add(a.getId());r.setTotal(r.getAsientoIds().size()*f.getPrecio());return repo.save(r);}public Reserva confirmar(String id){Reserva r=buscar(id);r.setEstado(EstadoReserva.CONFIRMADA);return repo.save(r);}public Reserva cancelar(String id){Reserva r=buscar(id);for(String asientoId:r.getAsientoIds())cines.buscarAsiento(asientoId).setOcupado(false);r.setEstado(EstadoReserva.CANCELADA);return repo.save(r);}public Reserva buscar(String id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Reserva",id));}public List<Reserva> porCliente(String clienteId){auth.buscar(clienteId);List<Reserva>x=new ArrayList<>();for(Reserva r:repo.findAll())if(clienteId.equals(r.getClienteId()))x.add(r);return x;}}
